def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    last_me, last_opp = history[-1]

    # Non-responsiveness check
    if n >= 12:
        my_D_next = 0
        my_D_count = 0
        my_C_next = 0
        my_C_count = 0
        for i in range(n - 1):
            if history[i][0] == 'D':
                my_D_count += 1
                if history[i + 1][1] == 'D':
                    my_D_next += 1
            else:
                my_C_count += 1
                if history[i + 1][1] == 'D':
                    my_C_next += 1
        if my_D_count >= 3 and my_C_count >= 3:
            p_D_given_D = my_D_next / my_D_count
            p_D_given_C = my_C_next / my_C_count
            if abs(p_D_given_D - p_D_given_C) < 0.25:
                return 'D'

    # Early cooperation
    if n < 6:
        return 'C'

    # Opponent has never defected
    if opp_d == 0:
        if my_d == 0:
            return 'D'
        else:
            return 'D'

    # We have never defected
    if my_d == 0:
        if opp_d > n * 0.3:
            return 'D'
        else:
            if last_opp == 'D':
                return 'D'
            else:
                return 'C'

    # Both have defected
    recent_opp_d = 0
    start = max(0, n - 5)
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    if opp_d > n * 0.7 or recent_opp_d >= 4:
        return 'D'

    retaliated = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'D':
            retaliated = True
            break

    if not retaliated:
        return 'D'

    if recent_opp_d >= 3:
        return 'D'
    else:
        return 'C'
